from io import StringIO
from dotenv import read_dotenv

config = read_dotenv(".env")  # e.g. {"USER": "foo", "EMAIL": "foo@example.org"}

# or from a stream, without interpolation:
config2 = read_dotenv(stream=StringIO("A=1\nB"), interpolate=False)  # {"A": "1", "B": None}

# merge with real environment variables taking priority:
import os
merged = {**read_dotenv(".env"), **os.environ}
